"""Inventory real chapter files and create a project-wide production board."""
import argparse
import html
from common import ROOT, chapter_entries, read_json, write_json, sha256, validate_project

GENERATED = {'docs/ASSET_INVENTORY.json', 'docs/PRODUCT_STATUS.json'}

def build_inventory(root=ROOT):
    registry = validate_project(root)
    contract = read_json(root / registry['product_contract'])
    rows = []
    for folder, meta in chapter_entries(root):
        assets = []
        for path in sorted(folder.rglob('*')):
            relative = path.relative_to(folder).as_posix()
            if path.is_file() and path.name != '.gitkeep' and relative not in GENERATED:
                assets.append({'path': relative, 'bytes': path.stat().st_size, 'sha256': sha256(path)})
        write_json(folder / 'docs/ASSET_INVENTORY.json', {'chapter': meta['slug'], 'files': assets})
        products = read_json(folder / 'docs/PRODUCTS.json')
        lanes = []
        for lane in contract['lanes']:
            files = [a['path'] for a in assets if a['path'].startswith(lane['folder'] + '/')]
            lanes.append({'id': lane['id'], 'files_present': len(files), 'status': 'available for review' if files else 'not supplied', 'required_deliverables': lane['deliverables']})
        status = {'chapter': meta['slug'], 'editorial_number': meta['number'], 'original_number': (meta['original_edition'] or {}).get('number'), 'reader': 'published manuscript' if meta['publish'] else 'outline only', 'v2_product_release': meta['production_status'], 'lanes': lanes, 'products': products['products'], 'remaining': products.get('remaining', []), 'v2_remaining': ['Review original chapter numbers, titles and URLs in derivatives before a v2 product release', 'Review chapter experience and media against the v2 design', 'Record new visual QA for changed deliverables'] if meta['original_edition'] else ['Complete the chapter workflow after the author manuscript is supplied']}
        write_json(folder / 'docs/PRODUCT_STATUS.json', status)
        rows.append({'slug': meta['slug'], 'number': meta['number'], 'title': meta['title'], 'reader': status['reader'], 'product_release': status['v2_product_release'], 'files': len(assets), 'bytes': sum(a['bytes'] for a in assets), 'products': len(products['products'])})
    summary = {'schema_version': 1, 'chapters': rows, 'policy': contract['status_policy']}
    write_json(root / 'docs/PRODUCTION_STATUS.json', summary)
    table = ['# Production status', '', 'Generated by `python scripts/build_inventory.py`. File counts are evidence of availability, not completed release gates. Product-level proof states and remaining work are in each chapter’s `docs/PRODUCT_STATUS.json`.', '', '| V2 | Chapter | Reader | Product state | Files |', '|---|---|---|---|---:|']
    table += [f'| {r["number"] if r["number"] is not None else "Archive"} | [{r["title"]}](../chapters/{r["slug"]}/README.md) | {r["reader"]} | {r["product_release"]} | {r["files"]} |' for r in rows]
    (root / 'docs/PRODUCTION_STATUS.md').write_text('\n'.join(table) + '\n', encoding='utf-8')
    cards = []
    for row in rows:
        slug = row['slug']
        cards.append(f'<tr><td>{html.escape(row["number"] or "Archive")}</td><td><a href="../chapters/{slug}/README.md">{html.escape(row["title"])}</a></td><td>{html.escape(row["reader"])}</td><td>{html.escape(row["product_release"])}</td><td>{row["files"]}</td><td><a href="../chapters/{slug}/docs/PRODUCT_STATUS.json">Products & remaining work</a></td></tr>')
    (root / 'docs/PROJECT_BOARD.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>.json production board</title><style>body{font:16px/1.5 system-ui;background:#f4f0e7;color:#203039;margin:32px}h1{font:42px Georgia}a{color:#295954}table{border-collapse:collapse;width:100%;background:#fffdf7}td,th{padding:12px;text-align:left;border-bottom:1px solid #ddd}th{background:#142b36;color:#eee}main{overflow-x:auto}p{max-width:900px}</style><h1>.json / Production board</h1><p>' + html.escape(contract['status_policy']) + '</p><main><table><thead><tr><th>V2</th><th>Chapter</th><th>Reader</th><th>Product release</th><th>Files</th><th>Details</th></tr></thead><tbody>' + ''.join(cards) + '</tbody></table></main></html>', encoding='utf-8')
    return summary

if __name__ == '__main__':
    argparse.ArgumentParser(description=__doc__).parse_args()
    result = build_inventory()
    print(f'Inventoried {len(result["chapters"])} chapter folders; wrote docs/PROJECT_BOARD.html.')
